/** CPR-A static contract only. Not registered in the service or SourceOwner. */
import {z} from 'zod';import {cid,chash,cn,cref,currentBindingSchema,need,parsed} from '../../utils/gradleOwnedCurrentSchema.js';import {currentLineageSchema} from '../../utils/gradleOwnedCurrentAuxiliary.js';import {serviceIdentitySchema} from '../../utils/gradleOwnedServiceOwners.js';import {canonicalOwnedJson as canonical,ownedDigest as hash} from '../../utils/gradleOwnedJson.js';
export const CPR_SPEC=Object.freeze({schema:'cpr.semantic-spec.v1',packing:'max-feasible-prefix-v1',layout:'cpr.actual-codec-bound.v1',entries:9,sourceBytes:41460,inventoryBytes:4096,batches:19,ranges:4,dataBytes:4096,innerBytes:8192,frameBytes:16384,wireBytes:67108864,workUnits:67108864});export const CPR_SPEC_DIGEST=hash(CPR_SPEC);
export const same=(a:unknown,b:unknown)=>a===undefined||b===undefined?a===b:canonical(a)===canonical(b);
export const cprEntry=z.object({kind:z.enum(['commit','payload']),index:cn.max(8),sha256:chash,byteLength:cn.positive().max(41460)}).strict();
export const cprRange=cprEntry.omit({sha256:true,byteLength:true}).extend({ordinal:cn.max(3),offset:cn.max(41460),length:cn.positive().max(4096),entry:z.object({sha256:chash,byteLength:cn.positive().max(41460)}).strict()}).strict();
export const cprContext=z.object({catalog:chash,manifest:chash,registryDigest:chash,deploymentDigest:chash,endpointId:cid,requestKeyId:cid,replyKeyId:cid,peer:serviceIdentitySchema,provider:serviceIdentitySchema,origin:serviceIdentitySchema.optional(),lineage:currentLineageSchema,binding:currentBindingSchema,snapshot:cref('snapshot'),checkpoint:cref('checkpoint-prepare'),pin:cref('read-pin'),metadataDigest:chash,inventoryDigest:chash}).strict();export type CprContext=z.infer<typeof cprContext>;export type CprRange=z.infer<typeof cprRange>;
export function context(input:unknown){const c=parsed(cprContext,input);need(['reader','authority-broker'].includes(c.peer.role)&&c.provider.role==='provider'&&c.binding.mode==='serving','permission_denied');need(same(c.binding.selected?.snapshot,c.snapshot)&&same(c.binding.selected?.checkpoint,c.checkpoint),'binding_mismatch');need(Object.entries(c.lineage).every(([k,v])=>(c.binding as any)[k]===v),'binding_mismatch');need(c.binding.providerBoot===c.provider.boot&&c.catalog===c.lineage.profileDigest,'binding_mismatch');need(c.peer.role==='reader'?c.origin===undefined:c.origin?.role==='reader','permission_denied');return c;}
const claim=z.object({specDigest:z.literal(CPR_SPEC_DIGEST),seed:cid,batchOrdinal:cn.max(18),batchCount:cn.positive().max(19),planDigest:chash,inventoryDigest:chash}).strict();
export const cprCommandSchema=z.object({schema:z.literal('osv-mcp.cgp.source-command.v3'),api:z.literal('aux.ReadSourceRanges'),purpose:z.literal('read'),operationId:chash,peer:serviceIdentitySchema,lineage:currentLineageSchema,binding:currentBindingSchema,payload:z.object({snapshot:cref('snapshot'),checkpoint:cref('checkpoint-prepare'),pin:cref('read-pin'),origin:serviceIdentitySchema.optional(),transferId:cid,plan:claim,ranges:z.array(cprRange).min(1).max(4),byteBudget:cn.positive().max(4096)}).strict(),requestDigest:chash}).strict();export type CprCommand=z.infer<typeof cprCommandSchema>;
export function wireIntent(input:CprCommand){const {requestDigest,...q}=input;return hash({domain:'cpr.wire-intent.v3',command:q});}
export function operation(c:CprContext,seed:string,transferId:string,batchOrdinal:number){return hash({domain:'cpr.operation-id.v3',peer:c.peer,provider:c.provider,lineage:c.lineage,seed,transferId,batchOrdinal});}
export function keys(c:CprContext,q:CprCommand){return {k:hash({domain:'cpr.operation-key.v3',peer:q.peer,destination:c.provider,api:q.api,operationId:q.operationId,lineage:q.lineage}),d:hash({domain:'cpr.guard-intent.v3',wire:q.requestDigest,manifest:c.manifest,purpose:q.purpose,owner:c.provider,catalog:c.catalog})};}
export function command(input:unknown){const q=parsed(cprCommandSchema,input),p=q.payload;need(p.plan.batchOrdinal<p.plan.batchCount,'binding_mismatch');let total=0;for(const [i,r]of p.ranges.entries()){need(r.ordinal===i&&r.offset+r.length<=r.entry.byteLength,'range_invalid');total+=r.length;if(i){const a=p.ranges[i-1]!,ak=a.kind==='commit'?0:1,rk=r.kind==='commit'?0:1;need(rk>ak||(rk===ak&&(r.index>a.index||(r.index===a.index&&r.offset>=a.offset+a.length))),'range_invalid');if(r.kind===a.kind&&r.index===a.index)need(same(r.entry,a.entry),'range_invalid');}}need(total===p.byteBudget&&wireIntent(q)===q.requestDigest,'binding_mismatch');return q;}
export function checkCommand(c:CprContext,q:CprCommand){command(q);need(same(q.peer,c.peer)&&same(q.lineage,c.lineage)&&same(q.binding,c.binding)&&same(q.payload.snapshot,c.snapshot)&&same(q.payload.checkpoint,c.checkpoint)&&same(q.payload.pin,c.pin)&&same(q.payload.origin,c.origin),'binding_mismatch');need(q.operationId===operation(c,q.payload.plan.seed,q.payload.transferId,q.payload.plan.batchOrdinal),'binding_mismatch');}
export function makeCommand(c:CprContext,seed:string,transferId:string,ordinal:number,count:number,planDigest:string,ranges:CprRange[]):CprCommand{const q:any={schema:'osv-mcp.cgp.source-command.v3',api:'aux.ReadSourceRanges',purpose:'read',operationId:operation(c,seed,transferId,ordinal),peer:c.peer,lineage:c.lineage,binding:c.binding,payload:{snapshot:c.snapshot,checkpoint:c.checkpoint,pin:c.pin,...(c.origin?{origin:c.origin}:{}),transferId,plan:{specDigest:CPR_SPEC_DIGEST,seed,batchOrdinal:ordinal,batchCount:count,planDigest,inventoryDigest:c.inventoryDigest},ranges,byteBudget:ranges.reduce((n,r)=>n+r.length,0)},requestDigest:'0'.repeat(64)};q.requestDigest=wireIntent(q);return command(q);}
export const cprResultSchema=z.object({schema:z.literal('osv-mcp.cgp.range-result.v3'),api:z.literal('ReadSourceRanges'),lineage:currentLineageSchema,requestDigest:chash,operationKey:chash,mode:z.literal('observed'),snapshot:cref('snapshot'),inventoryDigest:chash,transferId:cid,specDigest:z.literal(CPR_SPEC_DIGEST),planDigest:chash,batchOrdinal:cn.max(18),batchCount:cn.positive().max(19),parts:z.array(cprRange.omit({length:true}).extend({totalBytes:cn.positive().max(41460),bytes:z.string().max(5464).regex(/^[A-Za-z0-9+/]+={0,2}$/),sha256:chash}).strict()).min(1).max(4),live:z.literal(false)}).strict().refine(r=>r.batchOrdinal<r.batchCount&&r.parts.every((p,i)=>p.ordinal===i),{message:'result order'});

export const cprPlanCoreSchema=cprContext.pick({catalog:true,peer:true,provider:true,origin:true,lineage:true,binding:true,snapshot:true,checkpoint:true,pin:true,metadataDigest:true,inventoryDigest:true}).extend({domain:z.literal('cpr.plan-core.v3'),specDigest:z.literal(CPR_SPEC_DIGEST),seed:cid,transferId:cid,groups:z.array(z.array(cprRange).min(1).max(4)).min(1).max(19)}).strict();
export function validatePlanCore(input:unknown){const p=parsed(cprPlanCoreSchema,input);let previous:CprRange|undefined,total=0,entries=0,commits=0,payloads=0,payloadStarted=false;for(const group of p.groups){need(group.reduce((n,r)=>n+r.length,0)<=4096,'range_invalid');for(const [i,r]of group.entries()){need(r.ordinal===i&&r.offset+r.length<=r.entry.byteLength,'range_invalid');if(previous&&r.kind===previous.kind&&r.index===previous.index){need(r.offset===previous.offset+previous.length&&same(r.entry,previous.entry),'range_invalid');}else{if(previous)need(previous.offset+previous.length===previous.entry.byteLength,'range_invalid');need(r.offset===0,'range_invalid');if(r.kind==='commit'){need(!payloadStarted&&r.index===commits++,'inventory_invalid');}else{payloadStarted=true;need(r.index===payloads++,'inventory_invalid');}entries++;}total+=r.length;previous=r;}}need(previous&&previous.offset+previous.length===previous.entry.byteLength&&commits>0&&payloads>=4&&entries<=9&&total<=41460,'inventory_invalid');return p;}
